<?php require_once 'functions.php'; if(logged_in()){header('Location: index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){$st=$pdo->prepare('SELECT * FROM users WHERE username=? OR email=? LIMIT 1');$st->execute([trim($_POST['identity']??''),trim($_POST['identity']??'')]);$user=$st->fetch();if($user&&password_verify($_POST['password']??'',$user['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$user['id'],'full_name'=>$user['full_name'],'username'=>$user['username'],'role'=>$user['role']];flash('Welcome back, '.$user['full_name'].'!');header('Location: index.php');exit;}else{$error='Incorrect username/email or password.';}}
page_header('Log in'); ?><div class="auth-wrap"><form class="panel auth-panel" method="post"><p class="eyebrow">WELCOME BACK</p><h1>Log in</h1><p class="muted">Sign in to manage your reports.</p><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><label>Username or email<input name="identity" required value="<?=e($_POST['identity']??'')?>"></label><label>Password<input type="password" name="password" required></label><button class="button full" type="submit">Log in</button><p class="form-foot">New here? <a href="register.php">Create an account</a></p></form></div><?php page_footer(); ?>
